if (LOCAL_STORE) {
    try {
        datastore.load();
        botLogic.init(datastore.getData());
        // Einmalige Daten-Migration (u.a. alten CreatorBoost-DM-Verlauf modernisieren).
        try { if (botLogic.migrateDataOnBoot) { const _mig = botLogic.migrateDataOnBoot(); if (_mig && _mig.changed) { datastore.saveDebounced(); console.log('🧹 [Migration] ' + _mig.changed + ' alte CreatorBoost-DMs modernisiert'); } } } catch (e) { console.error('[migration] Fehler:', e.message); }
        console.log('[LOCAL_STORE] aktiv — /data + Schreibpfade + Cron laufen lokal aus ' + datastore.DATA_FILE);
    }
    catch (e) { console.error('[LOCAL_STORE] load/init fehlgeschlagen:', e.message); }
    // App-eigener Cron-Scheduler (ersetzt den Telegram-Bot-zeitCheck). Alle 60s,
    // idempotent (taeglich-Flags in d._lastEvents). Persistiert nur bei Aenderung.
    setInterval(async () => {
        try { await botLogic.zeitCheck(); datastore.saveDebounced(); }
        catch (e) { console.error('[LOCAL_STORE] zeitCheck Fehler:', e.message); }
    }, 60000);
}
// Hilfsfunktion: lokale bot-logic-Mutation ausfuehren + persistieren (LOCAL_STORE),
// sonst null zurueck (Aufrufer faellt auf den Bot-Proxy zurueck).
async function localWrite(fn) {
    const r = await fn();
    datastore.saveDebounced();
    return r;
}
// Wie localWrite, aber SOFORT (synchron, atomar) persistieren — fuer identitaets-/
// sicherheitskritische Mutationen (Signup, Passwort), damit sie auch bei einem
// harten Crash im 2s-Debounce-Fenster nicht verloren gehen.
async function localWriteNow(fn) {
    const r = await fn();
    try { datastore.save(); } catch (e) { console.error('[localWriteNow] save-Fehler:', e.message); }
    return r;
}
// Graceful Shutdown: ausstehende (debounced) Writes synchron flushen, damit bei
// Railway-Redeploys/Restarts (SIGTERM) kein bis-zu-2s-Fenster verloren geht.
let _shuttingDown = false;
function _flushAndExit(sig) {
    if (_shuttingDown) return; _shuttingDown = true;
    try { if (LOCAL_STORE) { datastore.save(); console.log('[shutdown] datastore geflusht (' + sig + ')'); } } catch (e) { console.error('[shutdown] flush-Fehler:', e.message); }
    process.exit(0);
}
process.on('SIGTERM', () => _flushAndExit('SIGTERM'));
process.on('SIGINT', () => _flushAndExit('SIGINT'));
// Profil-Update: unter LOCAL_STORE lokal via bot-logic, sonst Proxy an den Bot.
// (updateProfileApi nimmt den ganzen Body: bio/spitzname/email/confirmEmail/… )
async function _updateProfile(body) {
    return LOCAL_STORE ? await localWrite(() => botLogic.updateProfileApi(body)) : await _updateProfile(body);
}
// Mappt die Roulette/Daily-Credit-Actions (Bot-Pfade) auf die lokalen bot-logic-Funktionen.
function _localCreditAction(action, payload) {
    if (action === '/add-xp') return botLogic.addXp(payload);
    if (action === '/add-extra-link') return botLogic.addExtraLink(payload);
    if (action === '/add-diamonds') return botLogic.addDiamonds(payload);
    if (action === '/add-superlink') return botLogic.addSuperlink(payload);
    return null;
}
// Mappt die Admin-Grant-Actions (Dashboard) auf die lokalen bot-logic-Mutationen.
function _localGrantAction(action, payload) {
    switch (action) {
        case 'add-xp':          return botLogic.addXp(payload);
        case 'remove-xp':       return botLogic.removeXp(payload);
        case 'add-diamonds':    return botLogic.addDiamonds(payload);
        case 'remove-diamonds': return botLogic.removeDiamonds(payload);
        case 'add-extra-link':  return botLogic.addExtraLink(payload);
        case 'add-superlink':   return botLogic.addSuperlink(payload);
        case 'add-warn':        return botLogic.addWarn(payload);
        case 'remove-warn':     return botLogic.removeWarn(payload);
        default:                return null;
    }
}
