// Sessions von Disk laden
const sessions = new Map();
// PERF: Cache statischer HTML-Files in Memory (geladen beim ersten Request).
let _cachedSystemInfoHtml = null;
let _cachedDiamantenInfoHtml = null;

// ── GLOBAL IP RATE-LIMIT (gegen DoS/Scraper/Brute-Force) ──
// Sliding window 60s, 300 req/min (~5/sec sustained). Excess → 429.
const _globalIpRateMap = new Map();   // ip → timestamps[]
const _GLOBAL_RATE_WINDOW_MS = 60_000;
const _GLOBAL_RATE_MAX = 300;
// TRUST_PROXY env: nur wenn = '1', vertrauen wir X-Forwarded-For (Railway/Cloudflare setzen das).
// Sonst ist der Header spoofbar → Angreifer könnte beliebige IPs sperren oder eigenes Limit umgehen.
const _TRUST_PROXY = process.env.TRUST_PROXY === '1';
function _clientIp(req) {
    if (_TRUST_PROXY) {
        const xff = String(req.headers['x-forwarded-for'] || '').split(',')[0].trim();
        if (xff) return xff.slice(0, 64);
    }
    return String(req.socket?.remoteAddress || '').slice(0, 64);
}
function _globalIpRateCheck(ip) {
    if (!ip) return true;
    const now = Date.now();
    let arr = _globalIpRateMap.get(ip);
    if (!arr) { arr = []; _globalIpRateMap.set(ip, arr); }
    // Drop expired entries
    while (arr.length > 0 && now - arr[0] > _GLOBAL_RATE_WINDOW_MS) arr.shift();
    if (arr.length >= _GLOBAL_RATE_MAX) return false;
    arr.push(now);
    return true;
}
// Cleanup alle 5 Min: IPs ohne Aktivität entfernen.
setInterval(() => {
    const cutoff = Date.now() - _GLOBAL_RATE_WINDOW_MS * 2;
    for (const [ip, arr] of _globalIpRateMap.entries()) {
        if (arr.length === 0 || arr[arr.length - 1] < cutoff) _globalIpRateMap.delete(ip);
    }
}, 5 * 60 * 1000);
// Email-Magic-Link: persistiert (gegen Restart-Expiry).
const emailLoginTokens = new Map();   // token → { email, uid, exp }
const emailConfirmTokens = new Map(); // token → { email, uid, exp } (für /einstellungen Email-Bestätigung)
const accountUnlockTokens = new Map(); // token → { uid, exp } — nach Klick im Mail Settings-Edit freischalten
// Hilfsfunktionen für Token-Persistierung
function _loadTokenMap(file, map) {
    try {
        if (!fs.existsSync(file)) return;
        const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
        const now = Date.now();
        for (const [t, v] of Object.entries(raw || {})) {
            if (v && v.exp && v.exp > now) map.set(t, v);
        }
    } catch(e) {}
}
function _saveTokenMap(file, map) {
    try {
        const obj = {};
        for (const [t, v] of map.entries()) obj[t] = v;
        fs.writeFile(file, JSON.stringify(obj), () => {});
    } catch(e) {}
}
_loadTokenMap(EMAIL_LOGIN_TOKENS_FILE, emailLoginTokens);
_loadTokenMap(ACCOUNT_UNLOCK_TOKENS_FILE, accountUnlockTokens);
function saveEmailLoginTokens() { _saveTokenMap(EMAIL_LOGIN_TOKENS_FILE, emailLoginTokens); }
function saveAccountUnlockTokens() { _saveTokenMap(ACCOUNT_UNLOCK_TOKENS_FILE, accountUnlockTokens); }
// Auto-persist bei JEDER Mutation (Map.prototype patchen): wrappt set/delete mit debounced save.
let _emailLoginSaveT = null;
let _accountUnlockSaveT = null;
const _origELSet = emailLoginTokens.set.bind(emailLoginTokens);
const _origELDel = emailLoginTokens.delete.bind(emailLoginTokens);
emailLoginTokens.set = (k, v) => { const r = _origELSet(k, v); clearTimeout(_emailLoginSaveT); _emailLoginSaveT = setTimeout(saveEmailLoginTokens, 2000); return r; };
emailLoginTokens.delete = (k) => { const r = _origELDel(k); clearTimeout(_emailLoginSaveT); _emailLoginSaveT = setTimeout(saveEmailLoginTokens, 2000); return r; };
const _origAUSet = accountUnlockTokens.set.bind(accountUnlockTokens);
const _origAUDel = accountUnlockTokens.delete.bind(accountUnlockTokens);
accountUnlockTokens.set = (k, v) => { const r = _origAUSet(k, v); clearTimeout(_accountUnlockSaveT); _accountUnlockSaveT = setTimeout(saveAccountUnlockTokens, 2000); return r; };
accountUnlockTokens.delete = (k) => { const r = _origAUDel(k); clearTimeout(_accountUnlockSaveT); _accountUnlockSaveT = setTimeout(saveAccountUnlockTokens, 2000); return r; };
const emailRateLimit = new Map();      // email → lastRequestTs (Cooldown gegen Spam)
// AppCode-Brute-Force-Schutz: pro IP max 10 versch. Codes / 10 Min
const _codeBruteMap = new Map();       // ip → { codes: Set, ts: Date.now() }
function _codeBruteCheck(ip, code) {
    if (!ip) return true;
    const now = Date.now();
    const WINDOW = 10 * 60 * 1000;
    let entry = _codeBruteMap.get(ip);
    if (!entry || now - entry.ts > WINDOW) entry = { codes: new Set(), ts: now };
    entry.codes.add(code);
    _codeBruteMap.set(ip, entry);
    if (_codeBruteMap.size > 1000) {
        for (const [k, v] of _codeBruteMap) if (now - v.ts > WINDOW) _codeBruteMap.delete(k);
    }
    return entry.codes.size <= 10;
}
function _codeBruteReset(ip) { if (ip) _codeBruteMap.delete(ip); }
// In-Memory LRU für /appbild/* — vorher 180 sync Disk-Reads pro Feed-Render
const _appbildBufCache = new Map();    // cacheKey → {buf, mime, etag, ts}
const _APPBILD_LRU_MAX = 500;
const _APPBILD_CACHE_TTL = 60000;  // 60s — danach Cache-Eintrag wegwerfen damit Mainbot-Updates sichtbar werden
const _APPBILD_BOOT_TS = Date.now();  // Server-Start-Timestamp fuer Cache-Bust wenn lokale Datei fehlt
function _appbildLRUSet(key, val) {
    if (_appbildBufCache.size >= _APPBILD_LRU_MAX) {
        // Älteste Einträge zuerst rauswerfen (Map preserved insertion order)
        const toRemove = Math.floor(_APPBILD_LRU_MAX * 0.1);
        let removed = 0;
        for (const k of _appbildBufCache.keys()) {
            if (removed >= toRemove) break;
            _appbildBufCache.delete(k); removed++;
        }
    }
    _appbildBufCache.set(key, val);
}
// Bei Profilbild/Banner-Upload invalidate: in /api/upload-profilepic und /api/upload-banner
// wird _appbildBufCache.delete(uid + '/' + type) gesetzt (separate Edit).
const signupIpRateLimit = new Map();   // ip → { ts, n } — gegen Fake-Account-Spam + Email-Enumeration
const _helperAiRate = new Map();       // uid → { ts, n } — gegen Gemini-Spam (jeder Call kostet Geld), max 8/min/User
const _reciprocityRate = new Map();    // ownerUid → ts — Reziprozitäts-Push max 1×/Stunde (kein Spam bei vielen Likes)
// Signup-Email-Confirmation: tracking unconfirmed Users LOCAL (Mainbot wird NICHT angefasst).
// uid → { token, email, exp }. Persisted to disk via savePendingEmailConfirms.
const pendingEmailConfirms = new Map();
const SIGNUP_RATE_LIMIT_WINDOW = 60 * 60 * 1000; // 1 Stunde Fenster
const SIGNUP_RATE_LIMIT_MAX = 5;       // max 5 Signups pro Stunde pro IP
const RESEND_API_KEY = process.env.RESEND_API_KEY || '';
const EMAIL_FROM = process.env.EMAIL_FROM || 'CreatorX <onboarding@resend.dev>';
// Auth-/Email-Links IMMER aus vertrauenswürdiger Quelle bauen — NIEMALS aus
// req.headers.host (client-kontrolliert → Host-Injection kann Login-/Confirm-Tokens
// auf eine fremde Domain umleiten = Token-Leak).
const AUTH_BASE_URL = (process.env.APP_URL || 'https://www.creatorboostx.de').replace(/\/$/, '');
// Chat-Medien-URLs streng validieren BEVOR sie gespeichert/gerendert werden — sonst
// Stored-XSS (eine präparierte image/audio-URL bricht aus dem HTML-Attribut/onclick aus).
// Erlaubt nur data:image/ , data:audio/ , https:// oder App-relative Pfade, und keine
// Zeichen, mit denen man aus Attribut/JS-String ausbrechen könnte.
function _safeMediaUrl(v, kind) {
    if (typeof v !== 'string' || !v) return null;
    if (v.length > 8000000) return null;
    if (/["'<>`\s\\]/.test(v)) return null;
    const okData = kind === 'image' ? v.startsWith('data:image/') : v.startsWith('data:audio/');
    if (okData || v.startsWith('https://') || v.startsWith('/')) return v;
    return null;
}
const EMAIL_TOKEN_TTL = 24 * 60 * 60 * 1000;  // 24 Stunden (war 1h, zu kurz wenn Mail spät zugestellt)
const ACCOUNT_UNLOCK_TTL = 30 * 60 * 1000;    // 30 Min Edit-Window nach Unlock-Klick
const MAGIC_LINK_RATE_LIMIT = 30 * 1000;      // 30 Sek zwischen Magic-Link-Requests pro Email
const PW_RESET_RATE_LIMIT = 5 * 60 * 1000;    // 5 Min zwischen Password-Reset-Requests pro Email
const EMAIL_RATE_LIMIT = MAGIC_LINK_RATE_LIMIT; // Backward-compat alias
setInterval(() => {
    const now = Date.now();
    let confirmsRemoved = 0;
    let loginRemoved = 0;
    let unlockRemoved = 0;
    for (const [t, v] of emailLoginTokens.entries()) if (v.exp < now) { emailLoginTokens.delete(t); loginRemoved++; }
    for (const [t, v] of emailConfirmTokens.entries()) { if (v.exp < now) { emailConfirmTokens.delete(t); confirmsRemoved++; } }
    for (const [t, v] of accountUnlockTokens.entries()) if (v.exp < now) { accountUnlockTokens.delete(t); unlockRemoved++; }
    // BUG-FIX: Cleanup darf KEINE ':n'-Counter-Keys löschen (das sind Versuchszähler, kein Timestamp).
    // Sonst wurde der Brute-Force-Schutz alle 5min zurückgesetzt — effektiv kein Limit.
    for (const [e, ts] of emailRateLimit.entries()) {
        if (typeof e === 'string' && e.endsWith(':n')) continue;
        if (typeof ts === 'number' && now - ts > EMAIL_RATE_LIMIT * 2) {
            emailRateLimit.delete(e);
            emailRateLimit.delete(e + ':n');  // auch zugehörigen Counter mit löschen
            emailRateLimit.delete('pw:' + e + ':n');
        }
    }
    for (const [ip, v] of signupIpRateLimit.entries()) if (now - v.ts > SIGNUP_RATE_LIMIT_WINDOW) signupIpRateLimit.delete(ip);
    for (const [uid, v] of _helperAiRate.entries()) if (now - v.ts > 120000) _helperAiRate.delete(uid);
    for (const [uid, ts] of _reciprocityRate.entries()) if (now - ts > 3600000) _reciprocityRate.delete(uid);
    // Wenn Email-Confirm-Tokens gelöscht wurden: sofort auf Disk persistieren
    // (sonst werden expired tokens nach Restart aus alter Datei wiedergeladen — würde aber unten gefiltert, also nur Inkonsistenz)
    if (confirmsRemoved > 0) { try { savePendingEmailConfirms(); } catch(e) {} }
    if (loginRemoved > 0) saveEmailLoginTokens();
    if (unlockRemoved > 0) saveAccountUnlockTokens();
}, 5 * 60 * 1000);

// Daily claims tracker (persisted to file, keyed by "type:uid:date")
const DAILY_CLAIMS_FILE = DATA_DIR + '/daily_claims.json';
let _dailyClaims = {};
try { if (fs.existsSync(DAILY_CLAIMS_FILE)) _dailyClaims = JSON.parse(fs.readFileSync(DAILY_CLAIMS_FILE, 'utf8')); } catch(e) {}
// Node 20+'s ICU formatiert `en-CA` als "2026-05-13, 14:32" — `new Date()` darauf wirft
// "Invalid time value" → 500 auf /api/claim-daily-xp + /api/spin-roulette.
// Stattdessen formatToParts: lokale-unabhängig, immer YYYY-MM-DD.
const _berlinDateFmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin', year:'numeric', month:'2-digit', day:'2-digit' });
function getBerlinDate() {
    const parts = _berlinDateFmt.formatToParts(new Date());
    const get = (t) => (parts.find(p => p.type === t) || {}).value || '';
    return get('year') + '-' + get('month') + '-' + get('day');
}
function hasClaimed(type, uid) {
    return !!_dailyClaims[type + ':' + uid + ':' + getBerlinDate()];
}
function markClaimed(type, uid) {
    const today = getBerlinDate();
    _dailyClaims[type + ':' + uid + ':' + today] = Date.now();
    for (const k of Object.keys(_dailyClaims)) { const d = k.split(':').pop(); if (d !== today) delete _dailyClaims[k]; }
    fs.writeFile(DAILY_CLAIMS_FILE, JSON.stringify(_dailyClaims), () => {});
}

// In-memory email send log (last 200 entries, not persisted across restarts)
const _emailSendLog = [];
const EMAIL_LOG_MAX = 200;
function logEmailSend(to, subject, ok, error) {
    _emailSendLog.unshift({ to, subject, ok, error: error || null, ts: Date.now() });
    if (_emailSendLog.length > EMAIL_LOG_MAX) _emailSendLog.length = EMAIL_LOG_MAX;
}

async function sendEmail(to, subject, html) {
    if (!RESEND_API_KEY) { console.error('RESEND_API_KEY nicht gesetzt'); logEmailSend(to, subject, false, 'RESEND_API_KEY nicht gesetzt'); return false; }
    return new Promise(resolve => {
        const data = JSON.stringify({ from: EMAIL_FROM, to: [to], subject, html });
        const req = https.request({
            hostname: 'api.resend.com', path: '/emails', method: 'POST',
            headers: {
                'Authorization': 'Bearer ' + RESEND_API_KEY,
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(data)
            }
        }, res => {
            let buf = ''; res.on('data', c => buf += c);
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) { logEmailSend(to, subject, true, null); resolve(true); }
                else { const errMsg = 'HTTP ' + res.statusCode; console.error('Resend Error:', res.statusCode, buf.slice(0, 200)); logEmailSend(to, subject, false, errMsg); resolve(false); }
            });
        });
        req.on('error', e => { console.error('Resend Request Fehler:', e.message); logEmailSend(to, subject, false, e.message); resolve(false); });
        req.setTimeout(8000, () => { req.destroy(); logEmailSend(to, subject, false, 'Timeout'); resolve(false); });
        req.write(data); req.end();
    });
}

