loadBetaTesters();

let _appDbSaveTimer = null;
let _appDbLastSaveOk = null;     // ISO-Time des letzten erfolgreichen Schreibens
let _appDbLastRefreshOk = null;  // ISO-Time des letzten erfolgreichen Mainbot-Pulls
let _appDbLastRefreshTry = null; // letzter Versuch (auch fehlgeschlagen)
let _appDbRefreshFailures = 0;   // fortlaufende Fehlschläge (für Health-Check)

// ── Phase 2: Write-Audit-Log + Sync-Health ──
// Jede postBot-Mutation wird protokolliert (Rolling 5000 Einträge). Plus
// Fail-Counter für Mainbot-Calls damit ein Banner zeigt wann Bridge degraded ist.
const APP_WRITES_LOG = DATA_DIR + '/app_writes_log.json';
const _writeLog = [];           // in-memory, last 5000 entries
let _writeLogSaveTimer = null;
let _mainbotConsecutiveFails = 0;
let _lastMainbotSuccessAt = Date.now();
let _lastMainbotCallAt = 0;
function logWrite(endpoint, body, response, success, durationMs) {
    const entry = {
        ts: Date.now(),
        endpoint: String(endpoint||'').slice(0, 80),
        uid: String(body?.uid || body?.fromUid || body?.reporterUid || ''),
        success: !!success,
        ms: Number(durationMs)||0,
        responseOk: success && response && response.ok !== false,
        error: success ? null : 'no-response',
    };
    _writeLog.push(entry);
    if (_writeLog.length > 5000) _writeLog.splice(0, _writeLog.length - 5000);
    if (_writeLogSaveTimer) return;
    _writeLogSaveTimer = setTimeout(() => {
        _writeLogSaveTimer = null;
        const tmp = APP_WRITES_LOG + '.tmp';
        fs.writeFile(tmp, JSON.stringify(_writeLog.slice(-5000)), (e) => {
            if (e) { console.error('app_writes_log save failed:', e.message); return; }
            fs.rename(tmp, APP_WRITES_LOG, (re) => { if (re) console.error('app_writes_log rename failed:', re.message); });
        });
    }, 3000);
}
function loadWriteLogFromDisk() {
    try {
        if (!fs.existsSync(APP_WRITES_LOG)) return;
        const raw = fs.readFileSync(APP_WRITES_LOG, 'utf8');
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
            _writeLog.push(...parsed.slice(-5000));
            console.log('✅ app_writes_log.json geladen (' + _writeLog.length + ' Einträge)');
        }
    } catch(e) {
        console.error('app_writes_log load failed:', e.message);
    }
}
function _markMainbotSuccess() {
    _mainbotConsecutiveFails = 0;
    _lastMainbotSuccessAt = Date.now();
    _lastMainbotCallAt = Date.now();
}
function _markMainbotFail() {
    _mainbotConsecutiveFails++;
    _lastMainbotCallAt = Date.now();
}

function persistAppDb() {
    // Debounce 2s — schützt vor disk-thrash bei rapid-fire refreshes
    if (_appDbSaveTimer) return;
    _appDbSaveTimer = setTimeout(() => {
        _appDbSaveTimer = null;
        if (!_dataCache) return;
        // PERFORMANCE: async write — vorher sync writeFileSync blockierte Event-Loop
        // bei Multi-MB JSON oft 100-500ms (auf Railway 512MB-Instances).
        const tmp = APP_DB_FILE + '.tmp';
        fs.writeFile(tmp, JSON.stringify(_dataCache), (e) => {
            if (e) { console.error('app_db save failed:', e.message); return; }
            fs.rename(tmp, APP_DB_FILE, (re) => {
                if (re) { console.error('app_db rename failed:', re.message); return; }
                _appDbLastSaveOk = new Date().toISOString();
            });
        });
    }, 2000);
}

function loadAppDbFromDisk() {
    try {
        if (!fs.existsSync(APP_DB_FILE)) return false;
        const raw = fs.readFileSync(APP_DB_FILE, 'utf8');
        const parsed = JSON.parse(raw);
        const stat = fs.statSync(APP_DB_FILE);
        if (parsed && typeof parsed === 'object') {
            _dataCache = parsed;
            // MIGRATION-PHASE-1: Cache-Time vom File-Modified setzen, nicht Date.now().
            // Sonst denkt fetchBot() Cache ist frisch (45s TTL) und refreshed nicht sofort.
            _dataCacheTime = stat.mtimeMs;
            console.log('✅ app_db.json geladen (' + Object.keys(parsed.users||{}).length + ' users, age=' + Math.round((Date.now()-stat.mtimeMs)/1000) + 's)');
            return true;
        }
    } catch(e) {
        console.error('app_db load failed:', e.message);
    }
    return false;
}

// Boot-time: Disk laden BEVOR der Mainbot überhaupt erreichbar sein muss.
// Damit ist die App auch ohne Mainbot start-fähig.
const _bootHadDisk = loadAppDbFromDisk();
loadWriteLogFromDisk();
// MIGRATION-PHASE-1: Falls Boot ohne Snapshot UND ohne Mainbot — wenigstens leeres Skelett
// damit die App nicht crashed bei _dataCache.users[uid] Access.
if (!_bootHadDisk && !_dataCache) {
    _dataCache = { users: {}, _adminIds: [], _bootEmptyFallback: true };
    _dataCacheTime = 0;  // sofort als stale markiert, erster Mainbot-Refresh überschreibt
    console.log('⚠️  Boot ohne app_db.json + ohne Mainbot-Connect — leeres Skelett initialisiert.');
}
// Standalone: _dataCache aus dem lokalen Datastore seeden (autoritativ, statt evtl.
// veraltetem app_db.json-Snapshot). Danach hält der 45s-Refresh ihn aktuell.
if (LOCAL_STORE) {
    try { _dataCache = datastore.projectDataLikeBot(datastore.getData()); _dataCacheTime = Date.now(); }
    catch(e) { console.error('[LOCAL_STORE] _dataCache seed fehlgeschlagen:', e.message); }
}

// Mainbot stillgelegt: kein Bot-HTTP mehr. /data kommt aus dem lokalen Datastore,
// alles andere existiert nicht mehr -> null.
async function fetchBotRaw(path) {
    if (path === '/data') return datastore.projectDataLikeBot(datastore.getData());
    return null;
}

// Admin-Gate für Migrations-Routen: ?key=BRIDGE_SECRET ODER eingeloggter Admin.
async function _isAdminRequest(req, query) {
    if ((query?.key || '') === BRIDGE_SECRET && BRIDGE_SECRET) return true;
    const _sess = getSession(req);
    const _sessUid = _sess?.uid ? String(_sess.uid) : null;
    if (!_sessUid) return false;
    const _bd = await fetchBot('/data');
    const _adminIds = (Array.isArray(_bd?._adminIds) ? _bd._adminIds.map(Number) : []);
    return _adminIds.includes(Number(_sessUid)) || /admin/i.test(String(_bd?.users?.[_sessUid]?.role || ''));
}

// Dedizierter Fetch für den (potenziell großen) Migrations-Abzug — eigener
// langer Timeout statt fetchBotRaw (das ist auf kleines /data getunt).
function fetchRawExport() {
    return Promise.resolve({ error: 'Mainbot stillgelegt — Migration nicht mehr verfuegbar' });
}

let _refreshInFlight = null;
function refreshDataCache() {
    if (LOCAL_STORE) {
        // Standalone: _dataCache spiegelt den lokalen Datastore (kein Bot-Fetch mehr).
        try {
            _dataCache = datastore.projectDataLikeBot(datastore.getData());
            _dataCacheTime = Date.now();
            _appDbLastRefreshOk = new Date().toISOString();
            _appDbRefreshFailures = 0;
        } catch(e) { _appDbRefreshFailures++; }
        return Promise.resolve();
    }
    if (_refreshInFlight) return _refreshInFlight;
    _refreshInFlight = (async () => {
        _appDbLastRefreshTry = new Date().toISOString();
        try {
            const parsed = await fetchBotRaw('/data');
            if (parsed) {
                _dataCache = parsed;
                _dataCacheTime = Date.now();
                _appDbLastRefreshOk = new Date().toISOString();
                _appDbRefreshFailures = 0;
                persistAppDb();  // Snapshot auf Platte für nächsten Boot
            } else {
                _appDbRefreshFailures++;
            }
        } catch(e) {
            _appDbRefreshFailures++;
        } finally { _refreshInFlight = null; }
    })();
    return _refreshInFlight;
}

async function fetchBot(path) {
    if (LOCAL_STORE && path === '/data') return datastore.projectDataLikeBot(datastore.getData());
    if (path === '/data') {
        const now = Date.now();
        // Boot-Fallback (leere User-Map, Mainbot war beim Start nicht erreichbar) NICHT als
        // gültigen Cache behandeln — sonst rendert die erste Anfrage gegen eine leere Userliste
        // (User „ausgeloggt"/Admin-Listen leer). Erst auf einen echten Refresh warten.
        if (_dataCache && !_dataCache._bootEmptyFallback) {
            // Return cached data immediately (stale-while-revalidate)
            if ((now - _dataCacheTime) > DATA_CACHE_TTL) refreshDataCache();
            return _dataCache;
        }
        // No real cache yet - must wait
        await refreshDataCache();
        return _dataCache;
    }
    return fetchBotRaw(path);
}

// Optimistisches Cache-Patching nach einem Like: schreibt den Like SOFORT in den
// lokalen _dataCache, damit Feed-Poll/Reload ihn ohne Verzögerung zeigen — ohne auf
// einen vollen /data-Refetch warten zu müssen. Der Hintergrund-Refresh gleicht danach ab.
function _patchCacheLike(msgId, uid) {
    if (!_dataCache || !_dataCache.links) return;
    const links = _dataCache.links;
    const lnk = links[msgId] || links['B_'+msgId] || links['C_'+msgId]
        || Object.values(links).find(l => String(l.counter_msg_id) === String(msgId));
    if (!lnk) return;
    if (!Array.isArray(lnk.likes)) lnk.likes = [];
    if (!lnk.likes.map(String).includes(String(uid))) lnk.likes.push(String(uid));
}
function _patchCacheSuperlinkLike(slId, uid) {
    const sl = _dataCache && _dataCache.superlinks && _dataCache.superlinks[slId];
    if (!sl) return;
    if (!Array.isArray(sl.likes)) sl.likes = [];
    if (!sl.likes.map(String).includes(String(uid))) sl.likes.push(String(uid));
}

// ── SSE (Server-Sent Events): Echtzeit-Push an alle offenen Clients ──
// Single-Instance: alle Likes laufen durch diesen Prozess (/api/like), daher
// erreicht ein Broadcast jeden verbundenen Client sofort — kein Polling-Delay.
const sseClients = new Set(); // { res }
function sseBroadcast(event, data) {
    const payload = 'event: ' + event + '\ndata: ' + JSON.stringify(data) + '\n\n';
    for (const c of sseClients) {
        try { c.res.write(payload); } catch(e) { sseClients.delete(c); }
    }
}
// Like-Event: aggregierte Unique-Liker-Zahl + alle Element-IDs der gleichen URL broadcasten.
function sseBroadcastLike(msgId) {
    if (!_dataCache || !_dataCache.links) return;
    const links = _dataCache.links;
    const lnk = links[msgId] || links['B_'+msgId] || links['C_'+msgId]
        || Object.values(links).find(l => String(l.counter_msg_id) === String(msgId));
    if (!lnk) return;
    const set = new Set(); const ids = [];
    for (const [k,l] of Object.entries(links)) {
        if (l && l.text === lnk.text) {
            if (Array.isArray(l.likes)) for (const x of l.likes) set.add(String(x));
            ids.push(String(l.counter_msg_id||k)); ids.push(k);
        }
    }
    sseBroadcast('like', { ids: [...new Set(ids)], likes: set.size });
}
function sseBroadcastSuperlike(slId) {
    const sl = _dataCache && _dataCache.superlinks && _dataCache.superlinks[slId];
    if (!sl) return;
    sseBroadcast('superlike', { slId: String(slId), likes: Array.isArray(sl.likes) ? sl.likes.length : 0 });
}

// Pre-warm cache on startup and refresh every 45 seconds
setInterval(refreshDataCache, 45000);

// ── MIGRATION-PHASE-2: Write-Queue für Mainbot-Down-Failover ──
// Bei Mainbot-Timeout/Down werden idempotente Writes gequeued + alle 30s retried.
// Nicht-idempotente Writes (Signup, Password, Like) scheitern weiterhin direkt.
const WRITE_QUEUE_FILE = DATA_DIR + '/write_queue.json';
const _writeQueue = [];   // { id, ts, path, body, attempts, lastError }
const RETRYABLE_PATHS = new Set([
    '/update-profile-api',     // Profile-Edits (idempotent via uid+fields)
    '/log-email-login',         // Analytics
    '/log-funnel-api',          // Funnel-Tracking
    '/track-funnel',            // Funnel-Tracking
    '/app-presence',            // Heartbeat
    '/mark-post-seen',          // View-Stats
    '/complete-profile-api',    // Profile-Completion-Flag
    '/report-nonengager-api',   // Report (Konflikt nur bei doppelter Meldung)
]);
const MAX_QUEUE_ATTEMPTS = 20;  // ~10h max retries (jeder Versuch 30s apart)
const MAX_QUEUE_SIZE = 1000;    // unbounded growth verhindern

function loadWriteQueue() {
    try {
        if (!fs.existsSync(WRITE_QUEUE_FILE)) return;
        const parsed = JSON.parse(fs.readFileSync(WRITE_QUEUE_FILE, 'utf8'));
        if (Array.isArray(parsed)) {
            _writeQueue.push(...parsed.slice(0, MAX_QUEUE_SIZE));
            if (_writeQueue.length > 0) console.log('📥 Write-Queue geladen: ' + _writeQueue.length + ' Einträge');
        }
    } catch(e) { console.error('Write-queue load failed:', e.message); }
}
let _writeQueueSaveTimer = null;
function saveWriteQueue() {
    if (_writeQueueSaveTimer) return;
    _writeQueueSaveTimer = setTimeout(() => {
        _writeQueueSaveTimer = null;
        fs.writeFile(WRITE_QUEUE_FILE, JSON.stringify(_writeQueue), () => {});
    }, 1000);
}
function enqueueWrite(path, body) {
    if (_writeQueue.length >= MAX_QUEUE_SIZE) {
        console.warn('⚠️  Write-Queue voll (>' + MAX_QUEUE_SIZE + '), drop oldest');
        _writeQueue.shift();
    }
    _writeQueue.push({
        id: crypto.randomBytes(8).toString('hex'),
        ts: Date.now(),
        path,
        body,
        attempts: 0,
        lastError: null,
    });
    saveWriteQueue();
}
loadWriteQueue();

// Internal: low-level postBot WITHOUT queueing (used by retry-worker so it doesn't re-enqueue)
async function _postBotRaw(path, body) {
    return null;  // Mainbot stillgelegt — kein Bot-HTTP mehr.
}

// Background worker — alle 30s versucht queue abzuarbeiten
setInterval(async () => {
    if (_writeQueue.length === 0) return;
    if (_mainbotConsecutiveFails > 0) return;  // Mainbot scheint down, warten bis fetchBot wieder erfolgreich
    const batch = _writeQueue.splice(0, 10);
    let processed = 0, requeued = 0, dropped = 0;
    for (const item of batch) {
        const result = await _postBotRaw(item.path, item.body);
        if (result !== null) {
            processed++;
            _markMainbotSuccess();
        } else {
            item.attempts++;
            item.lastError = 'mainbot-timeout';
            _markMainbotFail();
            if (item.attempts >= MAX_QUEUE_ATTEMPTS) {
                dropped++;
                console.error('[write-queue] DROPPED after ' + MAX_QUEUE_ATTEMPTS + ' attempts: ' + item.path + ' (id=' + item.id + ')');
            } else {
                _writeQueue.push(item);  // an Ende zurück
                requeued++;
            }
        }
    }
    if (processed > 0 || dropped > 0) {
        console.log('[write-queue] processed=' + processed + ' requeued=' + requeued + ' dropped=' + dropped + ' remaining=' + _writeQueue.length);
        saveWriteQueue();
    }
}, 30000);

