// Sonntag 20:00 (Berlin TZ, schon global gesetzt) triggert Wochen-Gewinnspiel
// + Mindset-Stories-Pick im Mainbot. Mainbot kümmert sich weiterhin selbst um
// Daily/Wochen-Reset (intern). einmalig() Pattern verhindert Doppel-Trigger
// innerhalb einer Minute.
const _appCronSeen = {};
async function appCronTick() {
    try {
        const jetzt = new Date();
        const h = jetzt.getHours();
        const m = jetzt.getMinutes();
        const wochentag = jetzt.getDay();
        const tagStr = jetzt.toDateString();
        const einmalig = (key, fn) => {
            const fullKey = `${key}_${h}:${m}_${tagStr}`;
            if (_appCronSeen[fullKey]) return;
            _appCronSeen[fullKey] = true;
            return fn();
        };
        if (wochentag === 0 && h === 20 && m === 0) {
            einmalig('wochenGewinnspiel', async () => {
                console.log('🎰 [Cron] Trigger Wochen-Gewinnspiel');
                const r = LOCAL_STORE ? await localWrite(() => botLogic.runWochenGewinnspielApi()) : await postBot('/run-wochen-gewinnspiel-api', {});
                console.log('🎰 [Cron] Response:', r ? JSON.stringify(r) : 'null');
                // "Letzter Gewinner"-Anzeige (raffle-winners.json) mit dem ECHTEN Gewinner fuettern.
                if (LOCAL_STORE && r && r.ok && r.winnerId) {
                    try {
                        const _d = datastore.getData();
                        const wu = (_d.users || {})[String(r.winnerId)] || {};
                        const entry = {
                            uid: String(r.winnerId),
                            name: r.winnerName || wu.spitzname || wu.name || 'Creator',
                            handle: wu.ig_handle || wu.instagram || wu.username || '',
                            rang: wu.rang || '',
                            prize: '1 Extra-Link', prizeEmoji: '🔗',
                            xp: (_d.weeklyXP || {})[String(r.winnerId)] || 0,
                            participants: r.teilnehmer || 0,
                            timestamp: Date.now(),
                            week: new Date().toISOString().slice(0, 10)
                        };
                        const hist = loadRaffleHistory();
                        hist.lastWinner = entry;
                        hist.history = [entry, ...(hist.history || [])].slice(0, 12);
                        saveRaffleHistory(hist);
                    } catch(e) { console.error('[Gewinnspiel] Anzeige-Update Fehler:', e.message); }
                }
            });
            einmalig('mindsetPick', async () => {
                console.log('📖 [Cron] Trigger Mindset-Stories-Pick → Mainbot');
                const r = LOCAL_STORE ? await localWrite(() => botLogic.runMindsetPickApi()) : await postBot('/run-mindset-pick-api', {});
                console.log('📖 [Cron] Mainbot Response:', r ? JSON.stringify(r) : 'null');
            });
        }
        // Tägliches Backup: Window 03:00-03:05 (falls Server zu xx:00 nicht läuft, fängts in den 5 Min Catchup-Range).
        // Catchup wird in einmalig-Logik dedupliziert via Datum, läuft also pro Tag genau 1×.
        if (h === 3 && m <= 5) {
            einmalig('dailyBackup_' + tagStr, () => runDailyBackup().catch(e => console.error('[backup] Fehler:', e.message)));
        }
        // Auto-Pause: User, die >15 Tage nicht mehr in der App aktiv waren, automatisch (soft)
        // pausieren → raus aus Ranking/Explore/Suche/Stories. KEIN Datenverlust; Auto-Unpause
        // beim nächsten echten Request greift bereits (siehe ~5080). Window 04:00-04:05, 1×/Tag.
        if (h === 4 && m <= 5) {
            einmalig('autoPauseInactive_' + tagStr, () => {
                if (!LOCAL_STORE) return; // Schreiben nur im Standalone-Modus
                try {
                    const cutoff = Date.now() - 15 * 86400000;
                    const _d = datastore.getData();
                    const _adminIds = Array.isArray(_d._adminIds) ? _d._adminIds.map(Number) : [];
                    const toPause = [];
                    for (const [uid, u] of Object.entries(_d.users || {})) {
                        if (!u || u.paused || u.banned || u.parent_uid) continue; // schon pausiert/gebannt/Sub übersprungen
                        if (_adminIds.includes(Number(uid))) continue;            // Admins nie pausieren (pauseUserApi blockt zusätzlich)
                        const lastActive = Math.max(u.appLastSeen || 0, getLastSeen(uid) || 0);
                        if (!lastActive) continue;                                 // kein Aktivitäts-Signal → nicht anfassen
                        if (lastActive < cutoff) toPause.push(String(uid));
                    }
                    if (toPause.length) {
                        localWrite(() => { for (const uid of toPause) botLogic.pauseUserApi({ uid, reason: '15 Tage inaktiv', auto: true }); });
                        console.log('⏸️ [Cron] Auto-Pause: ' + toPause.length + ' inaktive User (>15 Tage) pausiert');
                    }
                } catch (e) { console.error('[auto-pause] Fehler:', e.message); }
            });
            // Win-back-Push BEVOR der User pausiert wird: Tag 7 + Tag 12 inaktiv → 1 persönlicher
            // Reminder (Flag _winbackStage gegen Doppel; reset bei Rückkehr im touchStreak/lastSeen-Hook
            // ist nicht nötig — wir prüfen lastActive-Fenster + Stage zusammen). Reaktiviert vor Verlust.
            einmalig('winbackInactive_' + tagStr, () => {
                if (!LOCAL_STORE) return;
                try {
                    const now = Date.now(), DAY = 86400000;
                    const _d = datastore.getData();
                    const _adminIds = Array.isArray(_d._adminIds) ? _d._adminIds.map(Number) : [];
                    let sent = 0;
                    for (const [uid, u] of Object.entries(_d.users || {})) {
                        if (!u || u.paused || u.banned || u.parent_uid || _adminIds.includes(Number(uid))) continue;
                        const lastActive = Math.max(u.appLastSeen || 0, getLastSeen(uid) || 0);
                        if (!lastActive) continue;
                        const days = Math.floor((now - lastActive) / DAY);
                        let stage = 0;
                        if (days >= 12 && days < 15) stage = 12;
                        else if (days >= 7 && days < 12) stage = 7;
                        if (!stage || u._winbackStage === stage) continue; // kein Treffer oder schon gesendet
                        const name = (u.spitzname || u.name || '').split(' ')[0] || '';
                        const msg = stage === 12
                            ? 'Dein Account wird bald pausiert. Schau kurz vorbei — deine Reels und dein Rang warten auf dich' + (name ? ', ' + name : '') + '.'
                            : 'Wir vermissen dich' + (name ? ', ' + name : '') + '. Neue Reels warten auf dein Engagement — bleib dran und halte deinen Rang.';
                        pushToUid(uid, stage === 12 ? '⏳ Komm zurück' : '👋 Lange nicht gesehen', msg, '/feed');
                        u._winbackStage = stage; sent++;
                    }
                    if (sent) { datastore.saveDebounced(); console.log('👋 [Cron] Win-back-Push an ' + sent + ' inaktive User'); }
                } catch (e) { console.error('[winback] Fehler:', e.message); }
            });
            // Community-Builder-Tagesbelohnung: jeder User mit Builder-Rang erhält 1×/Tag
            // seine rangabhängigen Diamanten (5/15/50/100 💎). cbDailyLastDay schützt vor Doppelzahlung.
            einmalig('cbDaily_' + tagStr, () => {
                if (!LOCAL_STORE || !botLogic.payCommunityBuilderDaily) return;
                try {
                    let res;
                    localWrite(() => { res = botLogic.payCommunityBuilderDaily(tagStr); });
                    if (res && res.paidUsers) console.log('💎 [Cron] Community-Builder-Tagesbelohnung: ' + res.paidUsers + ' User, ' + res.paidDiamonds + ' 💎');
                } catch (e) { console.error('[cb-daily] Fehler:', e.message); }
            });
        }
        // Tageswechsel: alte einmalig-Keys aufräumen, damit der Speicher nicht wächst.
        for (const key of Object.keys(_appCronSeen)) { if (!key.endsWith(tagStr)) delete _appCronSeen[key]; }
    } catch (e) { console.log('appCronTick Fehler:', e.message); }
}
setInterval(appCronTick, 60000);

// ── BACKUP-SYSTEM ──
// Tägliches Snapshot der wichtigen Daten-Files in /data/backups/YYYY-MM-DD/.
// Retention: 7 tägliche + 4 wöchentliche + 6 monatliche Backups.
const BACKUP_DIR = DATA_DIR + '/backups';
const BACKUP_FILES = [
    'app_db.json',
    'cb_sessions.json',
    'email_confirm_pending.json',
    'email_login_tokens.json',
    'account_unlock_tokens.json',
    'push_subscriptions.json',
    'beta_testers.json',
    'raffle-winners.json',
    'write_queue.json',
    'daily_claims.json',
];
// Backup-Status für Health-Endpoint (damit Admin merkt wenn Backups silent failen).
let _lastBackupStatus = { ts: null, copied: 0, skipped: 0, bytes: 0, errors: [] };
async function runDailyBackup() {
    // Nur wenn /data wirklich vorhanden ist — sonst sinnlos (Backups im Repo-Tree überleben Deploy nicht).
    if (DATA_DIR !== '/data') {
        console.warn('[backup] DATA_DIR != /data — Backups deaktiviert (kein persistent volume).');
        _lastBackupStatus = { ts: Date.now(), copied: 0, skipped: 0, bytes: 0, errors: ['no_persistent_volume'] };
        return;
    }
    const today = new Date();
    const dateStr = today.toISOString().slice(0, 10); // YYYY-MM-DD
    const backupDir = BACKUP_DIR + '/' + dateStr;
    try {
        await fs.promises.mkdir(backupDir, { recursive: true });
    } catch (e) {
        console.error('[backup] mkdir failed:', e.message);
        _lastBackupStatus = { ts: Date.now(), copied: 0, skipped: 0, bytes: 0, errors: ['mkdir:' + e.code] };
        return;
    }
    let copied = 0, skipped = 0, totalBytes = 0;
    const errors = [];
    for (const fname of BACKUP_FILES) {
        const src = DATA_DIR + '/' + fname;
        const dst = backupDir + '/' + fname;
        try {
            if (!fs.existsSync(src)) { skipped++; continue; }
            const data = await fs.promises.readFile(src);
            await fs.promises.writeFile(dst, data);
            copied++;
            totalBytes += data.length;
        } catch (e) {
            console.error(`[backup] ${fname} failed:`, e.message);
            errors.push(`${fname}:${e.code || e.message}`);
            // ENOSPC = disk voll: nicht weiter probieren, sonst tausende Errors.
            if (e.code === 'ENOSPC') { errors.push('DISK_FULL_ABORTED'); break; }
        }
    }
    _lastBackupStatus = { ts: Date.now(), copied, skipped, bytes: totalBytes, errors };
    console.log(`💾 [backup] ${dateStr}: ${copied} files copied (${(totalBytes/1024/1024).toFixed(2)} MB), ${skipped} skipped, ${errors.length} errors`);
    await cleanupOldBackups();
}
async function cleanupOldBackups() {
    // Retention: 7 tägliche + 4 wöchentliche (Sonntags) + 6 monatliche (1. Tag).
    try {
        if (!fs.existsSync(BACKUP_DIR)) return;
        const dirs = await fs.promises.readdir(BACKUP_DIR);
        const now = new Date();
        const cutoffDaily = new Date(now.getTime() - 7 * 86400000);
        const cutoffWeekly = new Date(now.getTime() - 4 * 7 * 86400000);
        const cutoffMonthly = new Date(now.getTime() - 6 * 31 * 86400000);
        let deleted = 0;
        for (const dir of dirs) {
            if (!/^\d{4}-\d{2}-\d{2}$/.test(dir)) continue;
            const d = new Date(dir);
            if (isNaN(d.getTime())) continue;
            const dayOfWeek = d.getDay();  // 0=Sunday
            const dayOfMonth = d.getDate();
            const keepAsMonthly = dayOfMonth === 1 && d > cutoffMonthly;
            const keepAsWeekly  = dayOfWeek === 0 && d > cutoffWeekly;
            const keepAsDaily   = d > cutoffDaily;
            if (!keepAsDaily && !keepAsWeekly && !keepAsMonthly) {
                try {
                    const path = BACKUP_DIR + '/' + dir;
                    const files = await fs.promises.readdir(path);
                    for (const f of files) await fs.promises.unlink(path + '/' + f).catch(()=>{});
                    await fs.promises.rmdir(path).catch(()=>{});
                    deleted++;
                } catch(e) { console.error(`[backup-cleanup] ${dir}:`, e.message); }
            }
        }
        if (deleted > 0) console.log(`🗑️  [backup-cleanup] ${deleted} alte Backup-Verzeichnisse entfernt`);
    } catch(e) { console.error('[backup-cleanup] failed:', e.message); }
}
async function listBackups() {
    try {
        if (!fs.existsSync(BACKUP_DIR)) return [];
        const dirs = await fs.promises.readdir(BACKUP_DIR);
        const result = [];
        for (const dir of dirs.sort().reverse()) {
            if (!/^\d{4}-\d{2}-\d{2}$/.test(dir)) continue;
            const path = BACKUP_DIR + '/' + dir;
            try {
                const files = await fs.promises.readdir(path);
                let totalBytes = 0;
                for (const f of files) {
                    const st = await fs.promises.stat(path + '/' + f).catch(()=>null);
                    if (st) totalBytes += st.size;
                }
                result.push({ date: dir, files: files.length, sizeBytes: totalBytes });
            } catch(e) {}
        }
        return result;
    } catch(e) { return []; }
}

const PARSE_BODY_MAX = 1024 * 1024; // 1MB cap; uploads use readBody with explicit limits
function parseBody(req) {
    return new Promise(resolve => {
        let body=''; let abort=false;
        req.on('data',c=>{
            if (abort) return;
            body += c;
            if (body.length > PARSE_BODY_MAX) { abort = true; req.destroy(); resolve({}); }
        });
        req.on('end',()=>{
            if (abort) return;
            try{resolve(JSON.parse(body));}catch(e){
                const p={};body.split('&').forEach(kv=>{const[k,v]=kv.split('=');if(k)p[decodeURIComponent(k)]=decodeURIComponent((v||'').replace(/\+/g,' '));});resolve(p);
            }
        });
        req.on('error', ()=>{ if(!abort){abort=true;resolve({});} });
    });
}

function xpNext(xp) {
    if(xp<50)return{ziel:'📘',fehlend:50-xp,pct:Math.round(xp/50*100)};
    if(xp<500)return{ziel:'⬆️',fehlend:500-xp,pct:Math.round((xp-50)/450*100)};
    if(xp<1000)return{ziel:'🏅',fehlend:1000-xp,pct:Math.round((xp-500)/500*100)};
    if(xp<5000)return{ziel:'👑',fehlend:5000-xp,pct:Math.round((xp-1000)/4000*100)};
    if(xp<10000)return{ziel:'🌟',fehlend:10000-xp,pct:Math.round((xp-5000)/5000*100)};
    return null;
}

function badgeGradient(role) {
    if(role?.includes('Legende')) return 'linear-gradient(135deg,#06b6d4,#0891b2,#67e8f9)';
    if(role?.includes('Elite+')) return 'linear-gradient(135deg,#00b4db,#a855f7,#f59e0b)';
    if(role?.includes('Elite')) return 'linear-gradient(135deg,#f59e0b,#ef4444)';
    if(role?.includes('Erfahrener')) return 'linear-gradient(135deg,#8b5cf6,#3b82f6)';
    if(role?.includes('Aufsteiger')) return 'linear-gradient(135deg,#3b82f6,#06b6d4)';
    if(role?.includes('Anfänger')) return 'linear-gradient(135deg,#10b981,#3b82f6)';
    return 'linear-gradient(135deg,#64748b,#94a3b8)';
}

const _bildCache = new Map();
const _BILD_CACHE_TTL = 120000;       // 2 min Daten-TTL (bisherig)
const _BILD_CACHE_MAX = 200;          // hartes Limit Einträge — verhindert unbounded growth
// Cache-Cleanup alle 5 Min: entferne abgelaufene Einträge + erzwinge Max-Größe.
setInterval(() => {
    const now = Date.now();
    for (const [k, v] of _bildCache.entries()) {
        if (now - (v?.ts || 0) > _BILD_CACHE_TTL * 5) _bildCache.delete(k);
    }
    if (_bildCache.size > _BILD_CACHE_MAX) {
        // Älteste zuerst (Map insertion-order)
        const overflow = _bildCache.size - _BILD_CACHE_MAX;
        const it = _bildCache.keys();
        for (let i = 0; i < overflow; i++) _bildCache.delete(it.next().value);
    }
}, 5 * 60 * 1000);

function ladeBild(uid, type) {
    // CreatorBoost-System-User: gebundeltes Avatar aus Repo.
    if (uid === 'creatorboost' && type === 'profilepic') return 'bundled';
    const key = uid + '_' + type;
    const hit = _bildCache.get(key);
    if (hit !== undefined && Date.now() - hit.ts < _BILD_CACHE_TTL) return hit.v;
    let v = null;
    try {
        const f = DATA_DIR + '/bild_' + uid + '_' + type + '.txt';
        if (fs.existsSync(f)) v = fs.readFileSync(f, 'utf8');
    } catch(e) {}
    _bildCache.set(key, {v, ts: Date.now()});
    return v;
}

// /appbild/UID/TYPE URL mit ?v=<mtime> Cache-Buster, damit Browser nach
// Upload sofort die neue Version laedt (Cache-Control kann lang bleiben).
// Gibt null zurueck wenn keine Datei existiert.
function appbildSrc(uid, type) {
    if (uid === 'creatorboost' && type === 'profilepic') return '/appbild/creatorboost/profilepic';
    try {
        const f = DATA_DIR + '/bild_' + uid + '_' + type + '.txt';
        if (!fs.existsSync(f)) return null;
        const m = Math.floor(fs.statSync(f).mtimeMs);
        return '/appbild/' + uid + '/' + type + '?v=' + m;
    } catch(e) { return null; }
}

function ladeProjectBild(uid, projectId) {
    try {
        const f = DATA_DIR + '/bild_' + uid + '_proj_' + projectId + '.txt';
        if (fs.existsSync(f)) return fs.readFileSync(f, 'utf8');
    } catch(e) {}
    return null;
}

function ladeProjectDoc(uid, projectId) {
    try {
        const f = DATA_DIR + '/doc_' + uid + '_proj_' + projectId + '.txt';
        if (fs.existsSync(f)) return fs.readFileSync(f, 'utf8');
    } catch(e) {}
    return null;
}

// _pinCache mit 60s TTL — pinned-Links aendern sich nur 1x pro 30 Tage.
// Vorher: bei /feed-Render wurden bis zu 1000 fs.existsSync + fs.readFileSync (1 pro User)
// gemacht -> riesiger Disk-IO Hit. Mit 60s TTL erfolgt das nur 1x/Minute pro User.
const _pinCache = new Map();
const _PIN_CACHE_TTL = 60000;
const _PIN_CACHE_MAX = 500;
function ladePinnedLink(uid) {
    const key = String(uid);
    const hit = _pinCache.get(key);
    if (hit && Date.now() - hit.ts < _PIN_CACHE_TTL) return hit.v;
    let v = null;
    try {
        const f = DATA_DIR + '/pinnedlink_' + key + '.txt';
        if (fs.existsSync(f)) v = fs.readFileSync(f, 'utf8').trim();
    } catch(e) {}
    if (_pinCache.size >= _PIN_CACHE_MAX) {
        // FIFO-Eviction: aelteste Eintrage zuerst
        const it = _pinCache.keys();
        for (let i = 0; i < 50; i++) _pinCache.delete(it.next().value);
    }
    _pinCache.set(key, { v, ts: Date.now() });
    return v;
}
function _invalidatePinCache(uid) { _pinCache.delete(String(uid)); }

