    if (document.hidden) return;
    if (Date.now() - _lastPing < 30000) return; // mindestens 30s zwischen Pings
    _lastPing = Date.now();
    try { fetch('/api/app-presence', { method:'POST', keepalive:true }).catch(()=>{}); } catch(e) {}
