    // Diese 5 Routes sind hier im File weiter unten definiert (~Z. 13900+), würden
    // also von der Auth-Gate gekapert ohne die Whitelist.
    if (!session) {
        if (!/^\/(datenschutz|privacy|impressum|agb|terms)$/.test(path)) {
            return redirect('/login');
        }
    }

    const d = await fetchBot('/data');
    if (!d) {
        res.writeHead(503,{'Content-Type':'text/html; charset=utf-8'});
        return res.end(layout('<div class="empty" style="margin-top:30vh"><div class="empty-icon">⚠️</div><div class="empty-text">Server nicht erreichbar</div><div class="empty-sub">Bitte versuche es später</div></div>', session, 'feed', lang));
    }

    const myUid = getMyUid(session);
    const myUser = d.users?.[myUid];
    const today = new Date().toDateString();
    // d.users könnte undefined sein wenn Bot leeres data zurückgibt → Object.entries(undefined) wäre crash.
    const adminIds = (Array.isArray(d._adminIds) ? d._adminIds.map(Number) : Object.entries(d.users || {}).filter(([,u])=>/admin/i.test(String((u && u.role)||''))).map(([id])=>Number(id)));
    const _myIsAdmin = adminIds.includes(Number(myUid));
    // 👑🥈🥉 Top-3 Ranking: gold (Top-1), silber (Top-2), bronze (Top-3).
    // Wird ÜBERALL angezeigt wo der Username gerendert wird (Posts, Kommentare, Liker, Stories etc).
    const _top3 = getTop3Uids(d, adminIds);
    const _top1Uid = _top3.top1;
    const crown = makeCrown(_top3);            // text prefix '👑 ' nur für Top-1 (Plain-Text-Contexts)
    const crownOverlay = makeCrownOverlay(_top3); // visuelles HTML-Crown mit Silber/Bronze für 2/3

    // ── API ENDPOINTS ──
    if (path === '/api/push-subscribe' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        const body = await parseBody(req);
        const { sub } = body;
        if (!sub?.endpoint) return json({ok:false});
        const hash = crypto.createHash('sha256').update(sub.endpoint).digest('hex').slice(0,16);
        // Push-Subscription gehört dem Gerät/Mensch — IMMER auf Parent-UID keyen, nicht auf
        // den gerade aktiven Sub. Sonst kriegt der Parent keine Pushes mehr nach Account-Switch.
        pushSubs[hash] = { uid: String(session.uid), sub };
        savePushSubs();
        return json({ok:true});
    }

    // Diagnose: Test-Push an den eingeloggten User selbst (Settings → "Test-Push").
    // Liefert sent/failed + bei Fehler den web-push-statusCode → zeigt ob Senden klappt.
    if (path === '/api/push-self-test' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!webpush) return json({ok:false, error:'web-push nicht verfügbar'});
        const _uid = String(getMyUid(session));
        const targets = Object.entries(pushSubs).filter(([,v]) => String(v.uid) === _uid);
        if (!targets.length) return json({ok:true, sent:0, failed:0, note:'keine Subscription gespeichert'});
        const payload = JSON.stringify({title:'🔔 Test-Push', body:'Push funktioniert! Wenn du das siehst, ist alles korrekt eingerichtet.', url:'/feed'});
        const results = await Promise.allSettled(targets.map(([,v]) => webpush.sendNotification(v.sub, payload)));
        let sent=0, failed=0, dirty=false; const errs=[];
        results.forEach((r,i)=>{ if(r.status==='fulfilled') sent++; else { failed++; const sc=r.reason?.statusCode; errs.push(sc||r.reason?.message||'err'); if(sc===410||sc===404){ delete pushSubs[targets[i][0]]; dirty=true; } } });
        if (dirty) savePushSubs();
        return json({ok:true, sent, failed, errors: errs.slice(0,3)});
    }

    // Push-Subscription für aktuellen Parent-User aufheben (alle Geräte dieses Users).
    // Falls Client den endpoint kennt → nur diese eine Sub löschen. Sonst alle.
    if (path === '/api/push-unsubscribe' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        const body = await parseBody(req).catch(()=>({}));
        const endpoint = body && body.endpoint;
        if (endpoint) {
            const hash = crypto.createHash('sha256').update(endpoint).digest('hex').slice(0,16);
            if (pushSubs[hash] && String(pushSubs[hash].uid) === String(session.uid)) delete pushSubs[hash];
        } else {
            for (const [k, v] of Object.entries(pushSubs)) {
                if (String(v.uid) === String(session.uid)) delete pushSubs[k];
            }
        }
        savePushSubs();
        return json({ok:true});
    }

    // Alle anderen Sessions dieses Users abmelden (außer aktuelle).
    if (path === '/api/logout-all-others' && req.method === 'POST') {
        if (!session) {
            res.writeHead(302, { 'Location': '/login' });
            return res.end();
        }
        const currentSid = getSid(req);
        let killed = 0;
        for (const [sid, s] of sessions) {
            if (s && String(s.uid) === String(session.uid) && sid !== currentSid) {
                sessions.delete(sid);
                killed++;
            }
        }
        if (killed) saveSessions();
        res.writeHead(302, { 'Location': '/einstellungen/sicherheit?cleared=' + killed });
        return res.end();
    }

    // Server-to-server push (vom main bot getriggert) — komplett zusätzlich, ändert nichts Bestehendes
    if (path === '/api/push-notify' && req.method === 'POST') {
        if (req.headers['x-bridge-secret'] !== BRIDGE_SECRET) return json({ok:false, error:'Forbidden'}, 403);
        if (!webpush) return json({ok:false, error:'web-push nicht verfügbar'});
        const body = await parseBody(req);
        const targetUid = String(body.uid||'');
        const title = String(body.title||'CreatorX').slice(0,80);
        const text = String(body.body||'').slice(0,180);
        const targetUrl = String(body.url||'/feed').slice(0,200);
        if (!targetUid || !text) return json({ok:false, error:'Fehlende Felder'});
        const payload = JSON.stringify({title, body:text, url:targetUrl});
        const targets = Object.entries(pushSubs).filter(([,v]) => String(v.uid) === targetUid);
        const results = await Promise.allSettled(targets.map(([,v]) => webpush.sendNotification(v.sub, payload)));
        let sent = 0, failed = 0, dirty = false;
        results.forEach((r,i) => {
            if (r.status === 'fulfilled') sent++;
            else { failed++; const sc = r.reason?.statusCode; if (sc===410||sc===404) { delete pushSubs[targets[i][0]]; dirty = true; } }
        });
        if (dirty || sent || failed) savePushSubs();
        return json({ok:true, sent, failed});
    }
    if (path === '/api/push-broadcast' && req.method === 'POST') {
        if (req.headers['x-bridge-secret'] !== BRIDGE_SECRET) return json({ok:false, error:'Forbidden'}, 403);
        if (!webpush) return json({ok:false, error:'web-push nicht verfügbar'});
        const body = await parseBody(req);
        const title = String(body.title||'CreatorX').slice(0,80);
        const text = String(body.body||'').slice(0,180);
        const targetUrl = String(body.url||'/feed').slice(0,200);
        const exceptUid = String(body.exceptUid||'');
        if (!text) return json({ok:false, error:'Fehlende Felder'});
        const payload = JSON.stringify({title, body:text, url:targetUrl});
        const targets = Object.entries(pushSubs).filter(([,v]) => !exceptUid || String(v.uid) !== exceptUid);
        const results = await Promise.allSettled(targets.map(([,v]) => webpush.sendNotification(v.sub, payload)));
        let sent = 0, failed = 0, dirty = false;
        results.forEach((r,i) => {
            if (r.status === 'fulfilled') sent++;
            else { failed++; const sc = r.reason?.statusCode; if (sc===410||sc===404) { delete pushSubs[targets[i][0]]; dirty = true; } }
        });
        if (dirty || sent || failed) savePushSubs();
        return json({ok:true, sent, failed});
    }

    if (path === '/api/theme' && req.method === 'POST') {
        const body = await parseBody(req);
        if(session && body.theme) { session.theme = String(body.theme); saveSessions(); }
        return json({ok:true});
    }
    if (path === '/api/lang' && req.method === 'POST') {
        const body = await parseBody(req);
        if(session && body.lang) { session.lang = String(body.lang); saveSessions(); }
        return json({ok:true});
    }
    if (path === '/api/save-profile' && req.method === 'POST') {
        const body = await parseBody(req);
        const updateData = { uid: myUid };
        if (body.bio !== undefined) updateData.bio = String(body.bio).slice(0, 100);
        if (body.spitzname !== undefined) updateData.spitzname = String(body.spitzname).slice(0, 30);
        // accentColor-Whitelist gegen JS-Injection im inline-Style/JS-Literal
        const ACCENT_WHITELIST = ['#ff6b6b','#ffa500','#00c851','#4dabf7','#cc5de8','#ffd43b','#ff8cc8','#20c997','#ff6348'];
        if (body.accentColor && ACCENT_WHITELIST.includes(body.accentColor)) updateData.accentColor = body.accentColor;
        if (body.nische !== undefined) updateData.nische = String(body.nische).slice(0, 50);
        // Website nur http(s) durchlassen
        if (body.website !== undefined) {
            const w = String(body.website).trim();
            updateData.website = w === '' ? '' : (/^https?:\/\//i.test(w) ? w.slice(0, 100) : '');
        }
        // Social-Handles: nur alphanumerisch + . _ - zugelassen, max 30 Zeichen (alle Plattformen).
        // Defense-in-depth gegen XSS-Strings — Output wird zwar geescaped, aber lieber am Boundary stoppen.
        // Bei invalid input UND nicht-leerem Wert: undefined returnen → kein Update (Bestandsdaten bleiben).
        // Bei leerem String '' explizit: leeren akzeptieren (User will Handle entfernen).
        const _sanitizeHandle = (v) => {
            const raw = String(v||'').trim();
            if (raw === '') return '';  // leer = User entfernt Handle
            const s = raw.replace(/^@/, '').slice(0, 30);
            // Nur a-z A-Z 0-9 . _ - erlaubt (Instagram/TikTok/YouTube/Twitter alle erlauben diese).
            return /^[a-zA-Z0-9._-]+$/.test(s) ? s : undefined;  // undefined = kein Update
        };
        const _maybeSetHandle = (field, val) => {
            const s = _sanitizeHandle(val);
            if (s !== undefined) updateData[field] = s;
        };
        if (body.tiktok !== undefined)    _maybeSetHandle('tiktok', body.tiktok);
        if (body.youtube !== undefined)   _maybeSetHandle('youtube', body.youtube);
        if (body.twitter !== undefined)   _maybeSetHandle('twitter', body.twitter);
        if (body.instagram !== undefined) _maybeSetHandle('instagram', body.instagram);
        if (body.banner !== undefined) updateData.banner = body.banner;
        // Email für Magic-Link-Login. Format-Validation auf Bot-Seite, Eindeutigkeits-Check ebenso.
        // Lock-Check: wenn User schon BEIDES (email + password) hat, braucht er Unlock-Window
        const _curBd = await fetchBot('/data');
        const _curUser = _curBd?.users?.[myUid] || {};
        const _isFullySet = !!_curUser.email && !!_curUser.password_hash;
        const _unlockActive = !!session && Number(session.accountUnlockUntil||0) > Date.now();
        let _emailActuallyChanged = false;
        if (body.email !== undefined) {
            const em = String(body.email||'').toLowerCase().trim();
            const emChanged = String(_curUser.email||'').toLowerCase() !== em;
            _emailActuallyChanged = emChanged;
            if (emChanged && _isFullySet && !_unlockActive) {
                return json({ok:false, error:'Email-Änderung gesperrt. Klick "Änderung anfragen" — wir senden dir einen Link zur Email zum Freischalten.', locked:true}, 423);
            }
            if (em === '' || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)) {
                updateData.email = em.slice(0, 200);
            } else {
                return json({ok:false, error:'Ungültige Email-Adresse'}, 400);
            }
        }
        // Passwort-Update direkt im Save-Profile (statt separat /api/auth/set-password aus Settings)
        let _pwUpdated = false;
        if (body.password && String(body.password).length > 0) {
            const pw = String(body.password);
            if (pw.length < 6 || pw.length > 200) return json({ok:false, error:'Passwort muss 6–200 Zeichen lang sein'}, 400);
            if (_isFullySet && !_unlockActive) {
                return json({ok:false, error:'Passwort-Änderung gesperrt. Klick "Änderung anfragen" zum Freischalten.', locked:true}, 423);
            }
            const pwResult = LOCAL_STORE
                ? await localWriteNow(() => botLogic.setUserPasswordApi({ uid: myUid, password: pw }))
                : await postBot('/set-user-password', { uid: myUid, password: pw });
            if (!pwResult || !pwResult.ok) return json({ok:false, error: (pwResult && pwResult.error) || 'Passwort speichern fehlgeschlagen'}, 500);
            _pwUpdated = true;
        }
        const updateResult = await _updateProfile(updateData);
        if (updateResult && updateResult.ok === false) {
            return json({ok:false, error: updateResult.error || 'Profile-Update fehlgeschlagen'});
        }
        // Email-Bestätigungs-Flow: wenn Email neu/geändert → Confirmation-Mail senden statt direkt zu speichern.
        let _emailPending = false;
        if (body.email !== undefined && updateData.email && updateData.email !== '') {
            // DIREKT (uncached) lesen — der gerade via update-profile-api geschriebene
            // pendingEmail ist im stale _dataCache noch nicht drin → sonst falsche
            // „Email bereits vergeben"-Meldung bzw. Bestätigungsmail wird nie verschickt.
            const _bd = LOCAL_STORE ? datastore.getData() : await fetchBotRaw('/data');
            const _u = _bd?.users?.[myUid] || {};
            // Eindeutigkeit-Konflikt? (Bot hat es nicht gespeichert AND auch nicht als pending)
            if (String(_u.email||'').toLowerCase() !== updateData.email && String(_u.pendingEmail||'').toLowerCase() !== updateData.email) {
                return json({ok:false, error:'Diese Email ist bereits einem anderen Account zugeordnet.'}, 409);
            }
            // Wenn als pending gespeichert (also unbestätigte Änderung) → Confirmation-Mail senden
            if (String(_u.pendingEmail||'').toLowerCase() === updateData.email) {
                try {
                    const token = crypto.randomBytes(24).toString('hex');
                    emailConfirmTokens.set(token, { email: updateData.email, uid: String(myUid), exp: Date.now() + EMAIL_TOKEN_TTL });
                    savePendingEmailConfirms();
                    const baseUrl = AUTH_BASE_URL;
                    const confirmUrl = baseUrl + '/auth/confirm-email?token=' + encodeURIComponent(token);
                    const userName = _u.spitzname || _u.name || 'CreatorX User';
                    const html = `<!DOCTYPE html><html><body style="margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#000;color:#fff;padding:0">
<div style="max-width:560px;margin:0 auto;padding:32px 24px">
<div style="text-align:center;margin-bottom:var(--space-6)"><img src="${baseUrl}/cx-logo-256.png" width="80" height="80" style="border-radius:18px" alt="CreatorX"></div>
<h1 style="font-size:26px;font-weight:700;margin:0 0 12px;text-align:center;color:#fff">Hi ${userName.replace(/[<>]/g,'')}!</h1>
<p style="font-size:15px;color:#a8a39a;line-height:1.6;text-align:center;margin:0 0 28px">Bestätige deine Email-Adresse <b style="color:#fff">${updateData.email}</b> für deinen CreatorX-Account. Klick den Button — der Link ist 24 Stunden gültig.</p>
<div style="text-align:center;margin:32px 0"><a href="${confirmUrl}" style="display:inline-block;background:linear-gradient(180deg,#f5d76e,#d4a946 50%,#8b6914);color:#000;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:700;font-size:15px;letter-spacing:0.3px">✅ Email bestätigen</a></div>
<p style="font-size:12px;color:#605c54;line-height:1.5;text-align:center;margin:32px 0 0;border-top:1px solid #221f1a;padding-top:var(--space-5)">Falls du diese Änderung nicht angefragt hast, ignoriere die Email — niemand kann deine Email-Adresse ohne Klick ändern.<br><br>Falls der Button nicht funktioniert, kopier diese URL in deinen Browser:<br><span style="color:#a8a39a;word-break:break-all;font-size:11px">${confirmUrl}</span></p>
</div></body></html>`;
                    sendEmail(updateData.email, '✅ Bestätige deine CreatorX-Email', html).catch(()=>{});
                    _emailPending = true;
                } catch(e) { console.log('Email-Confirm Send Fehler:', e.message); }
            }
        }
        if (session) {
            if (body.theme) session.theme = body.theme;
            if (body.lang) session.lang = body.lang;
            saveSessions();
        }
        await checkProfileCompletion(myUid, session);
        // Wenn Unlock-Window aktiv UND Email TATSÄCHLICH geändert ODER PW geändert → Window schließen.
        // Bug-Fix: vorher hat jedes body.email-Resubmit (auch unverändert) das Window geschlossen.
        if (session && _unlockActive && (_emailActuallyChanged || _pwUpdated)) {
            session.accountUnlockUntil = 0; saveSessions();
        }
        return json({ok:true, emailPending: _emailPending, pwUpdated: _pwUpdated});
    }

    if (path === '/api/follow' && req.method === 'POST') {
        const body = await parseBody(req);
        const targetUid = body && body.uid ? String(body.uid) : '';
        if (!targetUid) return json({ok:false, error:'Fehlende targetUid'},400);
        if (targetUid === myUid) return json({ok:false, error:'Kann dir nicht selbst folgen'},400);
        const result = LOCAL_STORE
            ? await localWrite(() => botLogic.followApi({ followerUid: String(myUid), targetUid }))
            : await postBot('/follow-api', { followerUid: String(myUid), targetUid });
        console.log('[follow] me=' + myUid + ' → ' + targetUid + ' result=' + JSON.stringify(result));
        if (result && result.ok === true) return json({ok:true, action: result.action});
        return json({ok:false, error: (result && result.error) ? result.error : 'Bot-API fehlgeschlagen'}, 500);
    }
    if (path === '/follow-form' && req.method === 'POST') {
        const body = await parseBody(req);
        const targetUid = body && body.uid ? String(body.uid) : '';
        const back = body && body.back ? String(body.back) : '/explore';
        if (targetUid && targetUid !== myUid) {
            if (LOCAL_STORE) await localWrite(() => botLogic.followApi({ followerUid: String(myUid), targetUid }));
            else await postBot('/follow-api', { followerUid: String(myUid), targetUid });
        }
        res.writeHead(302, { 'Location': back || '/explore' });
        return res.end();
    }

    if (path === '/api/post' && req.method === 'POST') {
        let body;
        try { body = JSON.parse(await readBody(req, 25000000)); } catch(e) { return json({ok:false, error:'Zu groß oder ungültig'},400); }
        const { text, attachment, attachmentType } = body;
        if (!text?.trim() && !attachment) return json({ok:false, error:'Text oder Datei erforderlich'},400);
        if (text && text.length > 300) return json({ok:false, error:'Max 300 Zeichen'},400);
        const result = LOCAL_STORE
            ? await localWrite(() => botLogic.createPostApi({ uid: myUid, text: (text||'').trim(), attachment, attachmentType }))
            : await postBot('/create-post-api', { uid: myUid, text: (text||'').trim(), attachment, attachmentType });
        if (!result) return json({ok:false, error:'Bot offline'}, 502);
        return json(result);
    }

    if (path === '/api/delete-post' && req.method === 'POST') {
        const body = await parseBody(req);
        const result = LOCAL_STORE
            ? await localWrite(() => botLogic.deletePostApi({ uid: myUid, timestamp: body.timestamp }))
            : await postBot('/delete-post-api', { uid: myUid, timestamp: body.timestamp });
        return json({ok: result?.ok === true, error: result?.error || null});
    }

    // Admin (oder Owner) löscht einen Reel-Link aus dem Feed.
    if (path === '/api/delete-link' && req.method === 'POST') {
        const body = await parseBody(req);
        const linkId = String(body.linkId || '').trim();
        if (!linkId) return json({ok:false, error:'linkId fehlt'}, 400);
        const _bd = await fetchBot('/data');
        if (!_bd) return json({ok:false, error:'Bot offline'}, 502);
        const link = _bd.links?.[linkId];
        if (!link) return json({ok:false, error:'Link nicht gefunden'}, 404);
        const _adminIds = Array.isArray(_bd._adminIds) ? _bd._adminIds.map(Number) : [];
        const isAdmin = _adminIds.includes(Number(myUid));
        const isOwner = String(link.user_id) === String(myUid);
        if (!isAdmin) return json({ok:false, error:'Nur Admins dürfen Links löschen'}, 403);
        if (LOCAL_STORE) {
            const r = await localWrite(() => botLogic.deleteLinkApi({ linkId }));
            return json({ ok: r?.ok === true, error: r?.error || null });
        }
        // Bot's /delete-link Bridge-Endpoint aufrufen (DELETE_LINK macht TG-Cleanup + d.links delete)
        try {
            const url = (process.env.MAINBOT_URL || '').replace(/\/$/, '') + '/delete-link?id=' + encodeURIComponent(linkId);
            const lib = url.startsWith('https') ? https : http;
            const u = new URL(url);
            await new Promise((resolve) => {
                const req2 = lib.request({hostname:u.hostname, port:u.port||(url.startsWith('https')?443:80), path:u.pathname+u.search, method:'GET', headers:{'x-bridge-secret': BRIDGE_SECRET}}, (res2) => {
                    res2.on('data',()=>{}); res2.on('end',resolve);
                });
                req2.on('error', resolve);
                req2.setTimeout(5000, () => { req2.destroy(); resolve(); });
                req2.end();
            });
        } catch(e) {}
        refreshDataCache();
        return json({ok:true});
    }

    if (path === '/api/delete-dm' && req.method === 'POST') {
        const body = await parseBody(req);
        const { chatKey, timestamp } = body;
        if (!chatKey || !timestamp) return json({ok:false, error:'Ungültig'}, 400);
        const [a, b] = chatKey.split('_');
        if (a !== myUid && b !== myUid) return json({ok:false, error:'Kein Zugriff'}, 403);
        const result = LOCAL_STORE
            ? await localWrite(() => botLogic.deleteDmApi({ chatKey, timestamp: Number(timestamp), uid: myUid }))
            : await postBot('/delete-dm-api', { chatKey, timestamp: Number(timestamp), uid: myUid });
        // !!result war true für {ok:false, error} → fake-success.
        return json({ok: result?.ok === true, error: result?.error || null});
    }

    if (path === '/api/delete-comment' && req.method === 'POST') {
        const body = await parseBody(req);
        const result = LOCAL_STORE
            ? await localWrite(() => botLogic.deleteCommentApi({ uid: myUid, postId: body.postId, commentIdx: body.commentIdx }))
            : await postBot('/delete-comment-api', { uid: myUid, postId: body.postId, commentIdx: body.commentIdx });
        return json({ok: result?.ok === true, error: result?.error || null});
    }

    if (path === '/api/post-link' && req.method === 'POST') {
        // Gate: nur Email-User müssen Insta setzen (Telegram-User haben bereits Identität).
        if (session.loginVia === 'email' && myUser && !myUser.instagram) return json({ok:false, error:'Bitte zuerst deinen Instagram-Username in den Einstellungen setzen.', missingInstagram:true}, 403);
        const body = await parseBody(req);
        const { url: linkUrl, caption } = body;
        if (!linkUrl || !linkUrl.includes('instagram.com')) return json({ok:false, error:'Nur Instagram Links'},400);
        const result = LOCAL_STORE
            ? await localWrite(() => botLogic.postLinkFromApp({ uid: myUid, name: session.name, url: linkUrl.trim(), caption: body.caption||'' }))
            : await postBot('/post-link-from-app', { uid: myUid, name: session.name, url: linkUrl.trim(), caption: body.caption||'' });
        if (!result) return json({ok:false, error:'Fehler beim Senden'},500);
        // BUGFIX: Bot-Fehler korrekt forwarden statt fake-{ok:true} zu retournieren.
        // Auch Web-Push nur bei explizitem ok:true (nicht bei undefined ok).
        if (result.ok === false) return json({ok:false, error: result.error || 'Posten fehlgeschlagen'});
        if (result.ok === true) {
            // First-Win: der allererste Post eines Neulings → SOFORT gezielter Begrüßungs-Push an
            // aktive User (nicht gebündelt), damit der/die Neue schnell erste Reaktionen bekommt.
            // Das erste erhaltene Like ist der stärkste Retention-Moment. Sonst normale Bündelung.
            if (result.firstPost) {
                const _pName = String(result.posterName || 'Ein neuer Creator');
                const _online = getOnlineUids();
                let _n = 0;
                for (const ouid of _online) {
                    if (String(ouid) === String(myUid)) continue;
                    pushToUid(ouid, '👋 Neu dabei', _pName + ' hat den ersten Reel geteilt — sei unter den Ersten mit einem Like.', '/feed');
                    if (++_n >= 25) break; // sanfter Cap gegen Push-Flut
                }
            } else {
                _queueLinkPush(myUid, session.name);
            }
        }
        return json({ok:true});
    }

    if (path === '/api/pin-post' && req.method === 'POST') {
        const body = await parseBody(req);
        const result = LOCAL_STORE ? await localWrite(() => botLogic.pinPostApi({ uid: myUid, timestamp: body.timestamp })) : await postBot('/pin-post-api', { uid: myUid, timestamp: body.timestamp });
        if (!result) return json({ok:false, error:'Bot offline'}, 502);
        return json(result);
    }

    if (path === '/api/engage-pinned-post' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'},401);
        const body = await parseBody(req);
        const ownerUid = String(body.ownerUid||'');
        if (!ownerUid || ownerUid === myUid) return json({ok:false, error:'Ungültig'},400);
        const result = LOCAL_STORE
            ? await localWrite(() => botLogic.engagePinnedPostApi({ engagerUid: myUid, ownerUid }))
            : await postBot('/engage-pinned-post-api', { engagerUid: myUid, ownerUid });
        return json({ok:!!result?.ok, alreadyDone: result?.alreadyDone||false, error: result?.error || null});
    }

    // Admin-Check für alle /api/admin/*-Routen unten — muss BEVOR die Routen
    // referenziert werden, sonst Temporal-Dead-Zone-Error → HTTP 500.
    // (Es gibt eine zweite Definition weiter unten — die ist redundant aber
    //  überschreibt diese nicht da const block-scoped ist; deshalb hier _early.)
    const _dashIsAdmin = (() => {
        const parentUid = String(session?.uid || '');
        return adminIds.includes(Number(myUid))
            || adminIds.includes(Number(parentUid))
            || String(d.users?.[myUid]?.role||'').includes('Admin')
            || String(d.users?.[parentUid]?.role||'').includes('Admin');
    })();

    // ── Report user (Schein-Engagement, Spam, etc.) ──
    if (path === '/api/report-user' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'},401);
        const body = await parseBody(req);
        const targetUid = String(body.targetUid||'');
        if (!targetUid || targetUid === myUid) return json({ok:false, error:'Ungültig'},400);
        const _rep = { reporterUid: myUid, targetUid, reason: String(body.reason||''), context: String(body.context||'') };
        const result = LOCAL_STORE ? await localWrite(() => botLogic.reportUserApi(_rep)) : await postBot('/report-user-api', _rep);
        return json(result || {ok:false, error:'Mainbot offline'});
    }

    // ── BLOCK / UNBLOCK / LIST BLOCKED USERS (Google-Play UGC-Pflicht) ──
    // Persistenz im Mainbot (Bridge), damit Block über Sub-Accounts hinweg + Server-Side
    // gefiltert wird. Bei Mainbot-Offline: best-effort, Fail mit Hinweis.
    if (path === '/api/block-user' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        const body = await parseBody(req);
        const targetUid = String(body.targetUid||'').trim();
        if (!targetUid || targetUid === myUid) return json({ok:false, error:'Ungültige Ziel-ID'}, 400);
        const result = LOCAL_STORE ? await localWrite(() => botLogic.blockUserApi({ blockerUid: myUid, targetUid })) : await postBot('/block-user-api', { blockerUid: myUid, targetUid });
        return json(result || {ok:false, error:'Mainbot offline — Block konnte nicht gespeichert werden, bitte später nochmal'});
    }

    if (path === '/api/unblock-user' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        const body = await parseBody(req);
        const targetUid = String(body.targetUid||'').trim();
        if (!targetUid) return json({ok:false, error:'Ungültige Ziel-ID'}, 400);
        const result = LOCAL_STORE ? await localWrite(() => botLogic.unblockUserApi({ blockerUid: myUid, targetUid })) : await postBot('/unblock-user-api', { blockerUid: myUid, targetUid });
        return json(result || {ok:false, error:'Mainbot offline'});
    }

    if (path === '/api/blocked-users' && req.method === 'GET') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        // Aus d.users[myUid].blockedUsers lesen — wird vom Mainbot beim Block geschrieben.
        const blocked = Array.isArray(d.users?.[myUid]?.blockedUsers) ? d.users[myUid].blockedUsers.map(String) : [];
        return json({ok:true, blocked});
    }

    // ── Admin: User als Sub-Account verknüpfen (z.B. Elitedrop → mein 3. Sub) ──
    if (path === '/api/admin/link-as-sub' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        const body = await parseBody(req);
        const target_uid = String(body.target_uid||'').trim();
        if (!target_uid) return json({ok:false, error:'target_uid erforderlich'},400);
        const r = LOCAL_STORE ? await localWrite(() => botLogic.adminLinkAsSubApi({ parent_uid: String(session.uid), target_uid })) : await postBot('/admin-link-as-sub-api', { parent_uid: String(session.uid), target_uid });
        return json(r || {ok:false, error:'Mainbot offline'});
    }

    // ── Admin Engagement-Log (pinned + collab + reports) ──
    if (path === '/api/admin/engagement-log' && req.method === 'GET') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        const result = LOCAL_STORE ? botLogic.adminEngagementLogApi() : await fetchBotRaw('/admin-engagement-log-api');
        return json(result || {ok:false, error:'Mainbot offline'});
    }

    if (path === '/api/admin/stats' && req.method === 'GET') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        const result = LOCAL_STORE ? botLogic.adminStatsApi() : await fetchBotRaw('/admin-stats-api');
        return json(result || {ok:false, error:'Mainbot offline'});
    }

    // Aktuell eingeloggte User (in-memory sessions). Aggregiert nach UID
    // (ein User kann mehrere Tabs/Geräte = mehrere Sessions haben).
    if (path === '/api/admin/online-users' && req.method === 'GET') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        const now = Date.now();
        const byUid = new Map();
        for (const s of sessions.values()) {
            if (!s || !s.uid) continue;
            const uid = String(s.uid);
            const last = s.lastSeen || 0;
            const ageMs = last ? (now - last) : Infinity;
            const cur = byUid.get(uid);
            if (!cur || last > cur.lastSeen) {
                byUid.set(uid, {
                    uid,
                    name: s.name || '–',
                    username: s.username || null,
                    loginVia: s.loginVia || 'unknown',
                    activeUid: s.activeUid ? String(s.activeUid) : uid,
                    isSubActive: s.activeUid && String(s.activeUid) !== uid,
                    sessionsCount: (cur ? cur.sessionsCount : 0) + 1,
                    lastSeen: last,
                    ageSec: Math.floor(ageMs / 1000),
                    sessionStart: s.createdAt || null,
                    online: ageMs < ONLINE_WINDOW_MS,
                });
            } else {
                cur.sessionsCount += 1;
            }
        }
        const list = Array.from(byUid.values())
            .sort((a, b) => (b.lastSeen || 0) - (a.lastSeen || 0));
        const onlineNow = list.filter(u => u.online).length;
        const totalSessions = sessions.size;
        return json({ ok: true, list, onlineNow, totalSessions, windowSec: Math.floor(ONLINE_WINDOW_MS / 1000) });
    }

    // Admin: Gewinnspiel-Gewinner manuell eintragen (z.B. wenn Cron-Eintrag fehlt)
    if (path === '/api/admin/raffle-winner' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        const body = await parseBody(req);
        const uid = String(body.uid || '').trim();
        const prize = String(body.prize || '').trim();
        const prizeEmoji = String(body.prizeEmoji || '🎁').trim();
        if (!uid || !prize) return json({ok:false, error:'uid und prize sind Pflicht'}, 400);
        const bd = await fetchBot('/data');
        const user = bd?.users?.[uid];
        if (!user) return json({ok:false, error:'User nicht gefunden'}, 404);
        const ts = body.timestamp ? Number(body.timestamp) : Date.now();
        const weekKey = new Date(ts).toISOString().slice(0,10);
        const xp = (bd.weeklyXP||{})[uid] || user.xpThisWeek || user.weeklyXp || 0;
        const entry = {
            uid,
            name: user.spitzname || user.name || 'Creator',
            handle: user.ig_handle || user.username || '',
            rang: user.rang || '',
            prize, prizeEmoji,
            xp, participants: 0,
            timestamp: ts, week: weekKey,
            manual: true
        };
        const hist = loadRaffleHistory();
        hist.lastWinner = entry;
        hist.history = [entry, ...(hist.history || [])].slice(0, 12);
        saveRaffleHistory(hist);
        return json({ok:true, entry});
    }

    // Admin: letzten Gewinnspiel-Eintrag löschen
    if (path === '/api/admin/raffle-winner-undo' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        const hist = loadRaffleHistory();
        if (!hist.history || !hist.history.length) return json({ok:false, error:'Keine Historie'}, 400);
        hist.history.shift();
        hist.lastWinner = hist.history[0] || null;
        saveRaffleHistory(hist);
        return json({ok:true});
    }

    if (path === '/api/admin/pause' && req.method === 'POST') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        const body = await parseBody(req);
        const r = LOCAL_STORE
            ? await localWrite(() => body.unpause ? botLogic.unpauseUserApi({ uid: String(body.uid||'') }) : botLogic.pauseUserApi({ uid: String(body.uid||'') }))
            : await postBot(body.unpause ? '/unpause-user-api' : '/pause-user-api', { uid: String(body.uid||'') });
        return json(r || {ok:false, error:'Mainbot offline'});
    }
    // ── REFERRAL-VERIFIZIERUNG (Admin): Liste offener Prüfungen + bestätigen/ablehnen ──
    if (path === '/api/admin/referral-pending' && req.method === 'GET') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        if (!LOCAL_STORE) return json({ok:true, pending:[]});
        return json(botLogic.referralPendingListApi());
    }
    // Komplette „Wer hat wen eingeladen"-Übersicht (alle Einlader + Eingeladene + Status)
    if (path === '/api/admin/referral-overview' && req.method === 'GET') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        if (!LOCAL_STORE) return json({ok:true, inviters:[], totalInviters:0, totalInvites:0, totalActive:0});
        return json(botLogic.referralOverviewApi());
    }
    // ── Papierkorb: gelöschte Accounts auflisten + wiederherstellen (Admin) ──
    if (path === '/api/admin/deleted-users' && req.method === 'GET') {
        if (!session) return json({ok:false, error:'Nicht eingeloggt'}, 401);
        if (!_dashIsAdmin) return json({ok:false, error:'Nur Admins'}, 403);
        if (!LOCAL_STORE) return json({ok:true, deleted:[], total:0});
        return json(botLogic.deletedUsersListApi());
    }
