    const _streakChip = _streakN >= 1 ? '<span style="display:inline-flex;align-items:center;gap:4px;flex-shrink:0;font-size:12px;font-weight:800;color:#f59e0b">'+(_streakN>=3?'🔥':'✨')+' '+_streakN+(_streakN===1?' Tag':' Tage')+'</span>' : '';
    let _ticker = '', _script = '';
