        const r = LOCAL_STORE ? botLogic.prismaLinkFeedApi(myUid, query.hideEngaged === '1') : await fetchBotRaw('/prisma-link-feed-api?uid=' + encodeURIComponent(myUid) + hideEngaged);
        return json(r || {ok:false, error:'Mainbot offline'});
